"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View2 from "./components/cta-sections/variants/03-portrait-frame";
const views={"portrait-frame":View2};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"portrait-frame"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="portrait-frame",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}

"use client";
import {useId} from "react";
// @zeus-internal
import {useArtemisReduceAfterHydration} from "../../../lib/use-reduce-after-hydration";
import { MotionConfig, motion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisCtaContent } from "../content";
const DEFAULT = {
    headline: "Too good to stay a side project.",
    subhead: "Open a shop that feels like you, from the first product drop to the thank-you page.",
    note: "Your products. Your name on the door.",
    cta: { label: "Create my shop", href: "#" },
    secondaryCta: { label: "See it in action", href: "#" },
    image: { src: "/assets/artemis/91d77a224e6a24bd5d55.webp", alt: "Coral over-ear headphones on a mint display plinth against a blue studio backdrop" },
} satisfies ArtemisCtaContent;
const IN_VIEW = { once: true } as const;
const HEADING_TRANSITION = { duration: 0.5, ease: ARTEMIS_EASE_OUT };
const FRAME_TRANSITION = { duration: 0.65, delay: 0.08, ease: ARTEMIS_EASE_OUT };
export default function CtaSectionsPortraitFrame({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
const artemisInstanceId=useId();

    const reduce = useArtemisReduceAfterHydration();
    const hover = reduce ? undefined : { scale: 1.01 };
    const tap = reduce ? undefined : { scale: 0.99 };
    return (<MotionConfig reducedMotion="user">
      <section aria-labelledby={`${artemisInstanceId}-title`} className="art:w-full art:px-4 art:py-8 art:@min-[768px]/artemis:px-8 art:@min-[768px]/artemis:py-12">
        <div className="art:relative art:isolate art:mx-auto art:max-w-7xl art:overflow-hidden art:rounded-3xl art:bg-background art:p-3 art:@min-[640px]/artemis:p-5 art:@min-[1024px]/artemis:p-9">
          <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:-z-10 art:overflow-hidden">
            <img src={copy.image.src} alt="" loading="lazy" decoding="async" className="art:size-full art:scale-125 art:object-cover art:blur-2xl art:saturate-150"/>
            <svg aria-hidden="true" className="art:absolute art:inset-0 art:size-full art:opacity-25">
              <defs>
                <filter id={`${artemisInstanceId}-grain`} x="0%" y="0%" width="100%" height="100%">
                  <feTurbulence type="fractalNoise" baseFrequency=".85" numOctaves="3" stitchTiles="stitch"/>
                  <feColorMatrix type="saturate" values="0"/>
                </filter>
              </defs>
              <rect width="100%" height="100%" filter={`url(#${artemisInstanceId}-grain)`}/>
            </svg>
          </div>
          <div data-artemis-theme="dark" className="art:relative art:grid art:gap-10 art:rounded-2xl art:bg-background art:p-6 art:text-foreground art:@min-[768px]/artemis:grid-cols-2 art:@min-[768px]/artemis:gap-8 art:@min-[768px]/artemis:p-8 art:@min-[1024px]/artemis:gap-14 art:@min-[1024px]/artemis:p-11">
            <div className="art:flex art:min-w-0 art:flex-col art:items-start art:justify-between art:gap-12 art:@min-[768px]/artemis:gap-20">
              <motion.h2 id={`${artemisInstanceId}-title`} className="art:max-w-sm art:text-balance art:text-4xl art:font-medium art:leading-tight art:tracking-tight" initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={IN_VIEW} transition={HEADING_TRANSITION}>
                {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
              </motion.h2>
              <div>
                <p className="art:max-w-sm art:text-pretty art:text-sm art:leading-relaxed art:@min-[768px]/artemis:text-base">
                  {copy.subhead}
                </p>
                <p className="art:mt-1 art:text-sm art:leading-relaxed art:text-foreground/70">
                  {copy.note}
                </p>
                <div className="art:mt-5 art:flex art:flex-col art:items-stretch art:gap-3 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:flex-wrap art:@min-[640px]/artemis:items-center">
                  <motion.a whileHover={hover} whileTap={tap} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:h-9 art:text-xs art:after:absolute art:after:inset-x-0 art:after:-inset-y-1 art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-foreground art:bg-foreground art:text-background art:hover:bg-foreground/90 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                    {copy.cta.label}
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5" aria-hidden="true">
                      <path d="M7 7h10v10"/>
                      <path d="M7 17 17 7"/>
                    </svg>
                  </motion.a>
                  <motion.a whileHover={hover} whileTap={tap} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:bg-transparent art:text-foreground art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:h-9 art:text-xs art:after:absolute art:after:inset-x-0 art:after:-inset-y-1 art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-foreground art:border-foreground/30 art:hover:bg-foreground/10 art:rounded-full" href={copy.secondaryCta.href} tabIndex={0}>
                    {copy.secondaryCta.label}
                  </motion.a>
                </div>
              </div>
            </div>
            <motion.div className="art:relative art:aspect-[4/3] art:w-full art:self-center art:overflow-hidden art:@min-[768px]/artemis:aspect-[5/4] art:@min-[1024px]/artemis:aspect-[4/3]" style={{ maskImage: "radial-gradient(circle at left top, transparent 27px, black 28px), radial-gradient(circle at right top, transparent 27px, black 28px), radial-gradient(circle at left bottom, transparent 27px, black 28px), radial-gradient(circle at right bottom, transparent 27px, black 28px)", maskComposite: "intersect" }} initial={{ opacity: 0, y: 14 }} whileInView={{ opacity: 1, y: 0 }} viewport={IN_VIEW} transition={FRAME_TRANSITION}>
              <img src={copy.image.src} alt={copy.image.alt} loading="lazy" decoding="async" width="1440" height="1080" className="art:size-full art:object-cover" style={{ objectPosition: "center" }}/>
            </motion.div>
          </div>
        </div>
      </section>
    </MotionConfig>);
}
